```cpp
#include <bits/stdc++.h>
using namespace std;

struct Edge {
	int u, v;
	int w;
};

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int n;
	if (!(cin >> n)) return 0;
	vector<Edge> edges;
	edges.reserve(n - 1);
	for (int i = 0; i < n - 1; ++i) {
		int u, v;
		int w;
		cin >> u >> v >> w;
		edges.push_back({u, v, w});
	}

	long long ans = 0;
	const long long NEG = (long long)-4e18;

	// 对每一位独立处理
	for (int b = 0; b < 30; ++b) {
		vector<char> forced1(n + 1, 0), forced0(n + 1, 0);
		vector<vector<int>> zeroAdj(n + 1);

		// 建“0-边”邻接，同时标出强制为1的点
		for (const auto &e : edges) {
			if ((e.w >> b) & 1) {
				forced1[e.u] = 1;
				forced1[e.v] = 1;
			} else {
				zeroAdj[e.u].push_back(e.v);
				zeroAdj[e.v].push_back(e.u);
			}
		}

		// 强制0：与强制1通过“0-边”相邻的点必须为0
		for (int u = 1; u <= n; ++u) if (forced1[u]) {
			for (int v : zeroAdj[u]) {
				forced0[v] = 1;
			}
		}

		long long countForced1 = 0;
		for (int u = 1; u <= n; ++u) if (forced1[u]) ++countForced1;

		// 在仅包含“0-边”的森林上做树形DP（跳过强制1的点）
		vector<char> vis(n + 1, 0);
		vector<long long> dp0(n + 1, 0), dp1(n + 1, 0);
		long long addFree = 0;

		for (int s = 1; s <= n; ++s) {
			if (forced1[s] || vis[s]) continue;

			// 迭代DFS（两阶段：入栈/出栈）以避免递归
			struct Item { int u, p, st; };
			vector<Item> st;
			st.reserve(64);
			st.push_back({s, 0, 0});
			vis[s] = 1;

			while (!st.empty()) {
				auto cur = st.back();
				st.pop_back();
				int u = cur.u, p = cur.p, state = cur.st;

				if (state == 0) {
					// 进入：稍后回溯计算，先压出栈标记
					st.push_back({u, p, 1});
					for (int v : zeroAdj[u]) {
						if (v == p || forced1[v] || vis[v]) continue;
						vis[v] = 1;
						st.push_back({v, u, 0});
					}
				} else {
					// 回溯：计算dp
					long long take0 = 0;
					long long take1 = forced0[u] ? NEG : 1;
					for (int v : zeroAdj[u]) {
						if (v == p || forced1[v]) continue;
						// v 已经在回溯阶段计算好
						long long c0 = dp0[v], c1 = dp1[v];
						take0 += max(c0, c1);
						if (take1 > NEG / 2) take1 += c0; // 若u=1，孩子必须取0
					}
					dp0[u] = take0;
					dp1[u] = take1;

					// 若是该连通分量根，累计贡献
					if (p == 0) {
						addFree += max(dp0[u], dp1[u]);
					}
				}
			}
		}

		long long ones = countForced1 + addFree;
		ans += ones * (1LL << b);
	}

	cout << ans << '\n';
	return 0;
}
