						dp0[u] = take0;
						dp1[u] = take1;
						if (p == 0) {
							addFree += Math.max(dp0[u], dp1[u]);
						}
					}
				}
			}

			long ones = countForced1 + addFree;
			ans += ones * (1L << b);
		}

		System.out.println(ans);
	}
