                        if v == p or forced1[v]:
                            continue
                        c0, c1 = dp0[v], dp1[v]
                        take0 += c0 if c0 >= c1 else c1
                        if take1 > NEG // 2:
                            take1 += c0
                    dp0[u] = take0
                    dp1[u] = take1
                    if p == 0:
                        addFree += dp0[u] if dp0[u] >= dp1[u] else dp1[u]

        ones = countForced1 + addFree
        ans += ones * (1 << b)

    print(ans)

if __name__ == "__main__":
